// MAPEO EXACTO AL LAYOUT DE FACTURATECH (comprobantes_layout.xlsx)
const body = $input.item.json.body || $input.item.json;

// 1. Datos del Cliente
const rawName = (body.customerName || body.clientName || body.name || "Cliente Consumidor Final").trim();
const rawEmail = (body.customerEmail || body.email || "").trim().toLowerCase();
const rawCountry = (body.country || body.pais || "ES").toUpperCase().trim();
const rawDoc = (body.documentId || body.dni || body.cedula || "").trim();
const rawSeller = (body.sellerCode || body.vendedor || "SOCIO-ES-01").trim();
const isSpain = rawCountry === "ES" || rawCountry === "ESPAÑA" || rawCountry === "ESP";

// 2. Fechas de la Suscripción (Formato YYYY-MM-DD)
const now = new Date();
const formatDate = (d) => d.toISOString().split("T")[0];
const fechaInicio = formatDate(now);
const fechaVencimiento = fechaInicio; // Contado vence de inmediato

const rawPlan = (body.plan || body.planName || "6 Meses VIP").toLowerCase();
let duracionDias = 180;
let planCode = "";
let planTitle = "";
let precioUnitario = 0;
let tipoFactura = isSpain ? 2 : 1; // 1: Venta Nacional | 2: Exportación
let moneda = isSpain ? "EUR" : "COP";
let trm = body.trm || 4450; // TRM oficial del día si es exterior

if (isSpain) {
  if (rawPlan.includes("12") || rawPlan.includes("anual")) {
    duracionDias = 365;
    planCode = "VIDEM-VIP-12";
    planTitle = "Suscripción Servicio Streaming Concierge (12 Meses)";
    precioUnitario = 89.99;
  } else if (rawPlan.includes("1") || rawPlan.includes("flex")) {
    duracionDias = 30;
    planCode = "VIDEM-FLEX-01";
    planTitle = "Servicio Streaming Concierge VIP (1 Mes)";
    precioUnitario = 9.99;
  } else {
    duracionDias = 180;
    planCode = "VIDEM-VIP-06";
    planTitle = "Suscripción Servicio Streaming Concierge (6 Meses)";
    precioUnitario = 49.99;
  }
} else {
  // Colombia
  if (rawPlan.includes("12") || rawPlan.includes("anual")) {
    duracionDias = 365;
    planCode = "VIDEM-CO-12";
    planTitle = "Asistencia Streaming Concierge Anual (12 Meses)";
    precioUnitario = 440000;
  } else if (rawPlan.includes("1") || rawPlan.includes("flex")) {
    duracionDias = 30;
    planCode = "VIDEM-CO-01";
    planTitle = "Asistencia Streaming Concierge (1 Mes)";
    precioUnitario = 55000;
  } else {
    duracionDias = 180;
    planCode = "VIDEM-CO-06";
    planTitle = "Asistencia Streaming Concierge VIP (6 Meses)";
    precioUnitario = 240000;
  }
}

const fechaFinObj = new Date(now.getTime() + (duracionDias * 24 * 60 * 60 * 1000));
const fechaFin = formatDate(fechaFinObj);

// 3. Documento Adquiriente
let nitAdquiriente = rawDoc;
if (!nitAdquiriente) {
  nitAdquiriente = isSpain ? ("CLI-ES-" + Math.floor(10000 + Math.random() * 90000)) : "222222222222";
}

// 4. Mapeo a las Columnas Exactas de comprobantes_layout.xlsx (Fila 4)
const layoutRow = {
  "*NIT ADQUIRIENTE": nitAdquiriente,
  "FECHA DE PAGO IMPUESTOS": "",
  "*TIPO DE OPERACIÓN": 10, // Estándar
  "*TIPO DE COMPROBANTE": 1, // Factura Electrónica
  "*TIPO DE FACTURA": tipoFactura, // 1 = Nacional | 2 = Exportación
  "FECHA INICIO PERIODO FACTURADO": fechaInicio,
  "FECHA FIN PERIODO FACTURADO": fechaFin,
  "*FECHA VENCIMIENTO": fechaVencimiento,
  "NOTAS": isSpain ? "Exportación de servicios exenta de IVA - Art. 481 literal c E.T." : "Operación de servicios tecnológicos en la nube excluida de IVA.",
  "*METODO DE PAGO": 1, // Contado
  "*MEDIO DE PAGO": 48, // 48: Tarjeta Crédito | 47: Transferencia
  "FECHA DE PAGO": fechaInicio,
  "*CANTIDAD": 1,
  "CODIGO": planCode,
  "PRODUCTO O SERVICIO": planTitle,
  "UNIDAD DE MEDIDA": "94", // Servicio / Unidad
  "INFORMACIÓN ADICIONAL": "Cliente: " + rawName + " | Email: " + rawEmail,
  "PRECIO UNITARIO": precioUnitario,
  "*CODIGO DEL ESTANDAR": "010", // Estándar de adopción del contribuyente
  "*CODIGO DEL PRODUCTO": planCode,
  "NÚMERO DE ELEMENTOS EN UN EMPAQUE": 1,
  "*ES CARGO (SI,NO)": "NO",
  "VALOR BASE PARA CÁLCULO": "",
  "PORCENTAJE DESCUENTO / CARGO": "",
  "*VALOR DESCUENTO/CARGO": 0,
  "DESCRIPCIÓN": "",
  "CODIGO IMPUESTO": "01", // IVA
  "BASE IMPONIBLE": precioUnitario,
  "TARIFA": 0,
  "UNIDAD DE MEDIDA BASE": "",
  "VALOR DEL TIRBUTO POR UNIDAD": "",
  "*IMPORTE IMPUESTO": 0,
  "MARCA": "VIDEM",
  "MODELO": "",
  "VALOR COMERCIAL": precioUnitario,
  "CODIGO DEL VENDEDOR": rawSeller,
  "SUBCODIGO DE VENDEDOR": "",
  "NIT DEL MANDANTE": "",
  "DÍGITO VERIFICADOR MANDANTE": "",
  "IDENTIFICADOR": "",
  "CARACTERÍSTICA": "",
  "DESCRIPCIÓN / VALOR": "",
  "TIPO DE CONCEPTO DE RECAUDO": "",
  "MONEDA DESTINO": moneda,
  "TIPO DE CAMBIO": isSpain ? trm : "",
  "FECHA DE TIPO DE CAMBIO": isSpain ? fechaInicio : ""
};

const summaryText = [
  "🧾 *NUEVA FILA DE FACTURACIÓN GENERADA (LOTE)*",
  "",
  "👤 *Cliente:* " + rawName + " (" + (isSpain ? "🇪🇸 España" : "🇨🇴 Colombia") + ")",
  "🆔 *Doc/NIT:* " + nitAdquiriente,
  "📦 *Plan:* " + planTitle,
  "💰 *Valor:* " + precioUnitario + " " + moneda,
  "📅 *Vigencia:* Del " + fechaInicio + " al " + fechaFin,
  "👤 *Vendedor:* " + rawSeller,
  "",
  "✅ Fila agregada a la plantilla de importación masiva de Facturatech."
].join("\n");

return {
  layoutRow,
  summaryText,
  rawName,
  rawEmail,
  planTitle,
  precioUnitario,
  moneda
};

// DEVUELVE EL CSV FORMATEADO EN UTF-8 LISTO PARA IMPORTAR EN FACTURATECH
// Lee los items acumulados de la base de datos o Google Sheets
const items = $input.all();
if (!items || items.length === 0) {
  return {
    headers: { "Content-Type": "text/plain; charset=utf-8" },
    body: "No hay facturas pendientes en el lote actual."
  };
}

const headers = Object.keys(items[0].json.layoutRow || items[0].json);
const rows = items.map(item => {
  const row = item.json.layoutRow || item.json;
  return headers.map(h => {
    const val = (row[h] !== undefined && row[h] !== null) ? String(row[h]) : "";
    return '"' + val.replace(/"/g, '""') + '"';
  }).join(",");
});

const csvContent = [headers.map(h => '"' + h + '"').join(","), ...rows].join("\r\n");

return {
  headers: {
    "Content-Type": "text/csv; charset=utf-8",
    "Content-Disposition": "attachment; filename=facturatech_lote_" + new Date().toISOString().split("T")[0] + ".csv"
  },
  body: csvContent
};
